object ScalaConsumer {
var checks = 0
def check(a: Long,e: Long): Unit = { assert(a == e); checks += 1 }
def check(a: Float,e: Float): Unit = { assert(if java.lang.Float.isNaN(e) then java.lang.Float.isNaN(a) else java.lang.Float.floatToRawIntBits(a) == java.lang.Float.floatToRawIntBits(e)); checks += 1 }
def check(a: Double,e: Double): Unit = { assert(if java.lang.Double.isNaN(e) then java.lang.Double.isNaN(a) else java.lang.Double.doubleToRawLongBits(a) == java.lang.Double.doubleToRawLongBits(e)); checks += 1 }
def main(args: Array[String]): Unit = { val p = new example.NumericAscriptions()
for x <- Array(0L,1L,-1L,Long.MinValue,Long.MaxValue,1099511627776L); b <- Array(false,true); n <- Array(-1,0,1,3) do {
check(p.long_identity(x,b,n),x)
check(p.long_literal(x,b,n),7L)
check(p.long_nested(x,b,n),x)
check(p.long_local_explicit(x,b,n),x)
check(p.long_local_inferred(x,b,n),x)
check(p.long_local_read(x,b,n),x)
check(p.long_assignment(x,b,n),x)
check(p.long_if_inside(x,b,n),(if b then x else 7L))
check(p.long_if_branches(x,b,n),(if b then x else 7L))
check(p.long_block_inside(x,b,n),x)
check(p.long_int_match_inside(x,b,n),(if n == 1 then x else 7L))
check(p.long_bool_match_inside(x,b,n),(if b then x else 7L))
check(p.long_bool_match_bodies(x,b,n),(if b then x else 7L))
check(p.long_return_value(x,b,n),x)
check(p.long_return_branch(x,b,n),(if b then x else 7L))
check(p.long_return_match(x,b,n),(if b then x else 7L))
check(p.long_effects(x,b,n),x)
check(p.long_loop(x,b,n),(if n > 0 then 7L else x))
}
for x <- Array(0.0f,-0.0f,java.lang.Float.MIN_VALUE,java.lang.Float.MAX_VALUE,java.lang.Float.POSITIVE_INFINITY,java.lang.Float.NEGATIVE_INFINITY,java.lang.Float.intBitsToFloat(0x7fc12345)); b <- Array(false,true); n <- Array(-1,0,1,3) do {
check(p.float_identity(x,b,n),x)
check(p.float_literal(x,b,n),0.5f)
check(p.float_nested(x,b,n),x)
check(p.float_local_explicit(x,b,n),x)
check(p.float_local_inferred(x,b,n),x)
check(p.float_local_read(x,b,n),x)
check(p.float_assignment(x,b,n),x)
check(p.float_if_inside(x,b,n),(if b then x else 0.5f))
check(p.float_if_branches(x,b,n),(if b then x else 0.5f))
check(p.float_block_inside(x,b,n),x)
check(p.float_int_match_inside(x,b,n),(if n == 1 then x else 0.5f))
check(p.float_bool_match_inside(x,b,n),(if b then x else 0.5f))
check(p.float_bool_match_bodies(x,b,n),(if b then x else 0.5f))
check(p.float_return_value(x,b,n),x)
check(p.float_return_branch(x,b,n),(if b then x else 0.5f))
check(p.float_return_match(x,b,n),(if b then x else 0.5f))
check(p.float_effects(x,b,n),x)
check(p.float_loop(x,b,n),(if n > 0 then 0.5f else x))
}
for x <- Array(0.0,-0.0,java.lang.Double.MIN_VALUE,java.lang.Double.MAX_VALUE,java.lang.Double.POSITIVE_INFINITY,java.lang.Double.NEGATIVE_INFINITY,java.lang.Double.longBitsToDouble(0x7ff8000000012345L)); b <- Array(false,true); n <- Array(-1,0,1,3) do {
check(p.double_identity(x,b,n),x)
check(p.double_literal(x,b,n),0.5)
check(p.double_nested(x,b,n),x)
check(p.double_local_explicit(x,b,n),x)
check(p.double_local_inferred(x,b,n),x)
check(p.double_local_read(x,b,n),x)
check(p.double_assignment(x,b,n),x)
check(p.double_if_inside(x,b,n),(if b then x else 0.5))
check(p.double_if_branches(x,b,n),(if b then x else 0.5))
check(p.double_block_inside(x,b,n),x)
check(p.double_int_match_inside(x,b,n),(if n == 1 then x else 0.5))
check(p.double_bool_match_inside(x,b,n),(if b then x else 0.5))
check(p.double_bool_match_bodies(x,b,n),(if b then x else 0.5))
check(p.double_return_value(x,b,n),x)
check(p.double_return_branch(x,b,n),(if b then x else 0.5))
check(p.double_return_match(x,b,n),(if b then x else 0.5))
check(p.double_effects(x,b,n),x)
check(p.double_loop(x,b,n),(if n > 0 then 0.5 else x))
}
check(p.minL(),Long.MinValue)
check(p.maxL(),Long.MaxValue)
check(p.zeroF(),-0.0f)
check(p.tinyF(),java.lang.Float.MIN_VALUE)
check(p.maxF(),java.lang.Float.MAX_VALUE)
check(p.zeroD(),-0.0)
check(p.tinyD(),java.lang.Double.MIN_VALUE)
check(p.maxD(),java.lang.Double.MAX_VALUE)
println(s"OK $checks checks")
}}
